mapper.update:
UPDATE registrations
SET status = #{status},
    waitlist_position = #{waitlistPosition},
    created_at = #{createdAt},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, session_id, player_id, status, waitlist_position, created_at, updated_at
FROM registrations
WHERE session_id = #{sessionId} AND player_id = #{playerId}

SELECT COUNT(*)
FROM registrations
WHERE session_id = #{sessionId} AND status = #{status}

SELECT COUNT(*)
FROM registrations
WHERE status = #{status}

mapper.update:
UPDATE registrations
SET waitlist_position = waitlist_position - 1,
    updated_at = CURRENT_TIMESTAMP
WHERE session_id = #{sessionId}
  AND status = 'WAITLISTED'
  AND waitlist_position > #{position}
